83	                                                async_overflow_policy overflow_policy) {
84	    if (overflow_policy == async_overflow_policy::block) {
85	        q_.enqueue(std::move(new_msg));
86	    } else if (overflow_policy == async_overflow_policy::overrun_oldest) {
87	        q_.enqueue_nowait(std::move(new_msg));
88	    } else {
89	        assert(overflow_policy == async_overflow_policy::discard_new);
90	        q_.enqueue_if_have_room(std::move(new_msg));
91	    }
92	}
